SELECT u.name AS memberName, LOWER(m.type) AS membershipType, m.type_rep AS typeRep, tu.name AS trainerName, p.payment_date AS paymentDate, p.payment_price AS paymentPrice, p.payment_fee AS paymentFee, (p.payment_price - p.payment_fee) AS netPrice, p.status AS status, p.canceled_at AS canceledAt, p.reason AS reason FROM PAYMENT p JOIN MEMBERSHIP m ON p.membership_num = m.membership_num JOIN `USER` u ON p.user_num = u.id LEFT JOIN TRAINER t ON m.trainer_num = t.id LEFT JOIN `USER` tu ON t.user_id = tu.id WHERE m.gym_num = #{gymNum}
AND DATE(p.payment_date) >= #{startDate}
AND DATE(p.payment_date) <= #{endDate}
AND LOWER(m.type) = #{membershipType}
AND t.id = #{trainerId}
AND p.status = #{status}
AND u.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.payment_date DESC LIMIT #{startRow}, #{pageSize}

SELECT COUNT(*)
FROM PAYMENT p
JOIN MEMBERSHIP m
  ON p.membership_num = m.membership_num
JOIN `USER` u
  ON p.user_num = u.id
LEFT JOIN TRAINER t
  ON m.trainer_num = t.id
WHERE m.gym_num = #{gymNum}


    AND DATE(p.payment_date) >= #{startDate}



    AND DATE(p.payment_date) <= #{endDate}



    AND LOWER(m.type) = #{membershipType}



    AND t.id = #{trainerId}



    AND p.status = #{status}



    AND u.name LIKE CONCAT('%', #{keyword}, '%')

SELECT IFNULL(SUM(p.payment_price), 0) AS totalSales, IFNULL(SUM(CASE WHEN LOWER(m.type) IN ('day', 'month') THEN p.payment_price ELSE 0 END), 0) AS gymSales, IFNULL(SUM(CASE WHEN LOWER(m.type) = 'pt' THEN p.payment_price ELSE 0 END), 0) AS ptSales, IFNULL(SUM(p.payment_fee), 0) AS totalFee, IFNULL(SUM(p.payment_price - p.payment_fee), 0) AS netSales, 0 AS growthRate FROM PAYMENT p JOIN MEMBERSHIP m ON p.membership_num = m.membership_num WHERE m.gym_num = #{gymNum} AND p.status = '결제완료'
AND DATE(p.payment_date) >= #{startDate}
AND DATE(p.payment_date) <= #{endDate}
AND LOWER(m.type) = #{membershipType}
AND m.trainer_num = #{trainerId}

SELECT DATE_FORMAT(p.payment_date, '%m/%d') AS label, IFNULL(SUM(p.payment_price), 0) AS sales, 0 AS percent FROM PAYMENT p JOIN MEMBERSHIP m ON p.membership_num = m.membership_num WHERE m.gym_num = #{gymNum} AND p.status = '결제완료'
AND DATE(p.payment_date) >= #{startDate}
AND DATE(p.payment_date) <= #{endDate}
AND LOWER(m.type) = #{membershipType}
GROUP BY DATE(p.payment_date), DATE_FORMAT(p.payment_date, '%m/%d') ORDER BY DATE(p.payment_date)

SELECT t.id AS trainerId, tu.name AS trainerName, tu.profileImg AS profileImg, IFNULL(SUM(p.payment_price), 0) AS totalSales, COUNT(ps.id) AS sessionCount FROM PAYMENT p JOIN MEMBERSHIP m ON p.membership_num = m.membership_num JOIN TRAINER t ON m.trainer_num = t.id JOIN `USER` tu ON t.user_id = tu.id LEFT JOIN PT_SESSION ps ON ps.trainer_id = t.id WHERE m.gym_num = #{gymNum} AND LOWER(m.type) = 'pt' AND p.status = '결제완료'
AND DATE(p.payment_date) >= #{startDate}
AND DATE(p.payment_date) <= #{endDate}
GROUP BY t.id, tu.name, tu.profileImg ORDER BY totalSales DESC LIMIT 5
